import * as fs from 'node:fs';

import {
  SchemaDefinition,
  SchemaDefinitionType,
  ToolDefinition,
} from 'aws-cdk-lib/aws-bedrockagentcore';

/**
 * Reads `contracts/generated/tools.json` and turns it into AgentCore `ToolDefinition`s.
 *
 * The file is generated by `make generate-tool-schemas` from
 * `src/adapters/inbound/tool_handlers/schemas.py`, and `make check-tool-schemas` fails if it is
 * stale. That is the whole point: a tool's input schema is what the *model* reads to decide what to
 * send and what Gateway validates against before the function is invoked, so it must exist once. A
 * hand-written copy in TypeScript beside the Python that dereferences those names is one fact in two
 * homes, and the two drift silently because each looks internally correct.
 *
 * JSON rather than anything richer for the same reason `tables.json` is JSON: the alternative is the
 * TypeScript side parsing a format nobody should write a parser for.
 *
 * **Validated on read rather than trusted.** The file is committed, so it is as likely to be stale
 * or hand-edited as any other input, and a malformed schema fails at gateway *creation* — after a
 * deploy has begun — with a message about a property rather than about a file. Failing here names
 * the file and the tool.
 */
export class GeneratedToolsError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'GeneratedToolsError';
    Object.setPrototypeOf(this, GeneratedToolsError.prototype);
  }
}

/** One tool as it appears in the generated file, before conversion. */
interface RawTool {
  readonly name: string;
  readonly description: string;
  readonly inputSchema: RawSchema;
}

interface RawSchema {
  readonly type: string;
  readonly description?: string;
  readonly items?: RawSchema;
  readonly properties?: Record<string, RawSchema>;
  readonly required?: string[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * The six types AgentCore names, mapped from the strings the generator emits.
 *
 * An explicit map rather than `SchemaDefinitionType.of(value)`, which accepts anything. A typo in
 * the generated file should fail here naming the tool, not reach gateway creation as a type the
 * service rejects.
 */
const TYPES: Readonly<Record<string, SchemaDefinitionType>> = {
  string: SchemaDefinitionType.STRING,
  number: SchemaDefinitionType.NUMBER,
  object: SchemaDefinitionType.OBJECT,
  array: SchemaDefinitionType.ARRAY,
  boolean: SchemaDefinitionType.BOOLEAN,
  integer: SchemaDefinitionType.INTEGER,
};

function readType(raw: unknown, where: string): SchemaDefinitionType {
  if (typeof raw !== 'string') {
    throw new GeneratedToolsError(`${where} has no type. Run \`make generate-tool-schemas\`.`);
  }
  const resolved = TYPES[raw];
  if (resolved === undefined) {
    throw new GeneratedToolsError(
      `${where} declares type "${raw}", which AgentCore does not define. ` +
        `Expected one of ${Object.keys(TYPES).join(', ')}.`,
    );
  }
  return resolved;
}

function readSchema(raw: unknown, where: string): SchemaDefinition {
  if (!isRecord(raw)) {
    throw new GeneratedToolsError(`${where} is not an object.`);
  }
  const type = readType(raw.type, where);

  // An array without an element type is accepted at synth and rejected at gateway creation, so it
  // is refused here where the message can name the argument.
  if (type === SchemaDefinitionType.ARRAY && raw.items === undefined) {
    throw new GeneratedToolsError(`${where} is an array and declares no items.`);
  }

  const properties = isRecord(raw.properties)
    ? Object.fromEntries(
        Object.entries(raw.properties).map(([name, nested]) => [
          name,
          readSchema(nested, `${where}.${name}`),
        ]),
      )
    : undefined;

  // Keys are omitted rather than set to `undefined`. `exactOptionalPropertyTypes` is on, and it is
  // on for a reason that applies here: an explicitly-undefined property is not the same as an
  // absent one, and CDK renders the difference into the template.
  return {
    type,
    ...(typeof raw.description === 'string' ? { description: raw.description } : {}),
    ...(raw.items === undefined ? {} : { items: readSchema(raw.items, `${where}[]`) }),
    ...(properties === undefined ? {} : { properties }),
    ...(Array.isArray(raw.required) ? { required: raw.required.map(String) } : {}),
  };
}

function readTool(raw: unknown, index: number): RawTool & { definition: ToolDefinition } {
  if (!isRecord(raw)) {
    throw new GeneratedToolsError(`tools[${index}] is not an object.`);
  }
  const { name, description } = raw;
  if (typeof name !== 'string' || name === '') {
    throw new GeneratedToolsError(`tools[${index}] has no name.`);
  }
  if (typeof description !== 'string' || description === '') {
    // Not cosmetic. The description is how a model decides whether a tool is the right one.
    throw new GeneratedToolsError(`${name} has no description, which the model reads.`);
  }
  const inputSchema = readSchema(raw.inputSchema, `${name}.inputSchema`);
  return {
    name,
    description,
    inputSchema: raw.inputSchema as RawSchema,
    // No `outputSchema`, and its absence was tested rather than assumed. `ToolDefinition` accepts
    // one, and declaring it does **not** give an AgentCore Policy guardrail anything to evaluate:
    // a policy scoped to `AgentCore::Action::"measurement"` still reports
    // `context.output.<field> is not present in the context of action`
    // [verified 2026-08-24 against dev]. See ADR-042.
    definition: { name, description, inputSchema },
  };
}

/** Every declared tool, keyed by the domain prefix of its name. */
export interface GeneratedTools {
  /** Tools whose name begins `catalog_`. Answered by the catalog function. */
  readonly catalog: ToolDefinition[];
  /** Tools whose name begins `measurement_`. Answered by the measurement function. */
  readonly measurement: ToolDefinition[];
}

/**
 * Load the generated tool definitions, split by the domain that answers them.
 *
 * Split on the name prefix rather than on a field in the file, because the prefix is already
 * load-bearing: `MeasurementTool` and `CatalogTool` are separate enums in Python and the handler
 * that owns a name is the one whose enum contains it. A second declaration of the same fact would
 * be one more thing able to disagree.
 */
export function loadGeneratedTools(filePath: string): GeneratedTools {
  let parsed: unknown;
  try {
    parsed = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
  } catch (error) {
    throw new GeneratedToolsError(
      `Could not read the generated tool schemas at ${filePath}: ${(error as Error).message}\n` +
        'Run `make generate-tool-schemas` to produce it.',
    );
  }

  if (!isRecord(parsed) || !Array.isArray(parsed.tools)) {
    throw new GeneratedToolsError(`${filePath} has no \`tools\` array.`);
  }

  const tools = parsed.tools.map((tool, index) => readTool(tool, index));
  if (tools.length === 0) {
    throw new GeneratedToolsError(`${filePath} declares no tools.`);
  }

  const catalog = tools.filter((tool) => tool.name.startsWith('catalog_'));
  const measurement = tools.filter((tool) => tool.name.startsWith('measurement_'));

  const unclaimed = tools.filter((tool) => !catalog.includes(tool) && !measurement.includes(tool));
  if (unclaimed.length > 0) {
    // A tool no function answers is a Gateway target pointing nowhere, which presents to a user as
    // a tool that exists and always fails.
    throw new GeneratedToolsError(
      `No function answers ${unclaimed.map((t) => t.name).join(', ')}. ` +
        'A tool name must begin `catalog_` or `measurement_`.',
    );
  }

  return {
    catalog: catalog.map((tool) => tool.definition),
    measurement: measurement.map((tool) => tool.definition),
  };
}
